@Test
public void sideInputsNotReadyResultHasUnprocessedElements() {
    PCollectionView<Integer> singletonView = inputPc.apply(Window.into(new IdentitySideInputWindowFn())).apply(View.<Integer>asSingleton().withDefaultValue(0));
    RecorderFn fn = new RecorderFn(singletonView);
    PCollection<Integer> output = inputPc.apply(ParDo.of(fn).withSideInputs(singletonView));
    CommittedBundle<Integer> inputBundle = bundleFactory.createRootBundle(inputPc).commit(Instant.now());
    UncommittedBundle<Integer> outputBundle = bundleFactory.createBundle(inputBundle, output);
    when(evaluationContext.createBundle(inputBundle, output)).thenReturn(outputBundle);
    ParDoInProcessEvaluator<Integer> evaluator = createEvaluator(singletonView, fn, inputBundle, output);
    IntervalWindow nonGlobalWindow = new IntervalWindow(new Instant(0), new Instant(10_000L));
    WindowedValue<Integer> first = WindowedValue.valueInGlobalWindow(3);
    WindowedValue<Integer> second = WindowedValue.of(2, new Instant(1234L), nonGlobalWindow, PaneInfo.NO_FIRING);
    WindowedValue<Integer> third = WindowedValue.of(1, new Instant(2468L), ImmutableList.of(nonGlobalWindow, GlobalWindow.INSTANCE), PaneInfo.NO_FIRING);
    evaluator.processElement(first);
    evaluator.processElement(second);
    evaluator.processElement(third);
    InProcessTransformResult result = evaluator.finishBundle();
    assertThat(result.getUnprocessedElements(), Matchers.<WindowedValue<?>>containsInAnyOrder(second, WindowedValue.of(1, new Instant(2468L), nonGlobalWindow, PaneInfo.NO_FIRING)));
    assertThat(result.getOutputBundles(), Matchers.<UncommittedBundle<?>>contains(outputBundle));
    assertThat(RecorderFn.processed, containsInAnyOrder(1, 3));
    assertThat(Iterables.getOnlyElement(result.getOutputBundles()).commit(Instant.now()).getElements(), Matchers.<WindowedValue<?>>containsInAnyOrder(first.withValue(8), WindowedValue.timestampedValueInGlobalWindow(6, new Instant(2468L))));
}

