    final TimerData addedTimer = TimerData.of(StateNamespaces.window(IntervalWindow.getCoder(), new IntervalWindow(new Instant(0).plus(Duration.standardMinutes(5)), new Instant(1).plus(Duration.standardMinutes(5)).plus(Duration.standardHours(1)))), new Instant(54541L), TimeDomain.EVENT_TIME);
    final TimerData deletedTimer = TimerData.of(StateNamespaces.window(IntervalWindow.getCoder(), new IntervalWindow(new Instant(0), new Instant(0).plus(Duration.standardHours(1)))), new Instant(3400000), TimeDomain.SYNCHRONIZED_PROCESSING_TIME);
    ParDo.Bound<String, KV<String, Integer>> pardo = ParDo.of(new DoFn<String, KV<String, Integer>>() {

        @Override
        public void processElement(ProcessContext c) {
            c.windowingInternals().stateInternals();
            c.windowingInternals().timerInternals().setTimer(TimerData.of(StateNamespaces.window(IntervalWindow.getCoder(), new IntervalWindow(new Instant(0).plus(Duration.standardMinutes(5)), new Instant(1).plus(Duration.standardMinutes(5)).plus(Duration.standardHours(1)))), new Instant(54541L), TimeDomain.EVENT_TIME));
            c.windowingInternals().timerInternals().deleteTimer(TimerData.of(StateNamespaces.window(IntervalWindow.getCoder(), new IntervalWindow(new Instant(0), new Instant(0).plus(Duration.standardHours(1)))), new Instant(3400000), TimeDomain.SYNCHRONIZED_PROCESSING_TIME));
        }
    });
    PCollection<KV<String, Integer>> mainOutput = input.apply(pardo);
    StructuralKey<?> key = StructuralKey.of("myKey", StringUtf8Coder.of());
    CommittedBundle<String> inputBundle = bundleFactory.createRootBundle(input).commit(Instant.now());
    InProcessEvaluationContext evaluationContext = mock(InProcessEvaluationContext.class);
    UncommittedBundle<KV<String, Integer>> mainOutputBundle = bundleFactory.createRootBundle(mainOutput);
    when(evaluationContext.createBundle(inputBundle, mainOutput)).thenReturn(mainOutputBundle);
    InProcessExecutionContext executionContext = new InProcessExecutionContext(null, key, null, null);
    when(evaluationContext.getExecutionContext(mainOutput.getProducingTransformInternal(), inputBundle.getKey())).thenReturn(executionContext);
    CounterSet counters = new CounterSet();
    when(evaluationContext.createCounterSet()).thenReturn(counters);
    TransformEvaluator<String> evaluator = new ParDoSingleEvaluatorFactory().forApplication(mainOutput.getProducingTransformInternal(), inputBundle, evaluationContext);
    evaluator.processElement(WindowedValue.valueInGlobalWindow("foo"));
    InProcessTransformResult result = evaluator.finishBundle();
    assertThat(result.getTimerUpdate(), equalTo(TimerUpdate.builder(StructuralKey.of("myKey", StringUtf8Coder.of())).setTimer(addedTimer).deletedTimer(deletedTimer).build()));
}

