public void duringCallGetThreadIsNonNull() throws Exception {
    final InProcessTransformResult result = StepTransformResult.withoutHold(downstream.getProducingTransformInternal()).build();
    final CountDownLatch testLatch = new CountDownLatch(1);
    final CountDownLatch evaluatorLatch = new CountDownLatch(1);
    TransformEvaluator<Object> evaluator = new TransformEvaluator<Object>() {

        @Override
        public void processElement(WindowedValue<Object> element) throws Exception {
            throw new IllegalArgumentException("Shouldn't be called");
        }

        @Override
        public InProcessTransformResult finishBundle() throws Exception {
            testLatch.countDown();
            evaluatorLatch.await();
            return result;
        }
    };
    when(registry.forApplication(created.getProducingTransformInternal(), null, evaluationContext)).thenReturn(evaluator);
    TransformExecutor<String> executor = TransformExecutor.create(registry, Collections.<ModelEnforcementFactory>emptyList(), evaluationContext, null, created.getProducingTransformInternal(), completionCallback, transformEvaluationState);
    Executors.newSingleThreadExecutor().submit(executor);
    testLatch.await();
    assertThat(executor.getThread(), not(nullValue()));
    // Finish the execution so everything can get closed down cleanly.
    evaluatorLatch.countDown();
}

