    assertThat(secondOutput.commit(Instant.now()).getElements(), containsInAnyOrder(tgw(11L), tgw(12L), tgw(14L), tgw(18L), tgw(19L), tgw(17L), tgw(16L), tgw(15L), tgw(13L), tgw(10L)));
}

